const fs = require('fs');

(function main() {
  const data = fs.readFileSync(0, 'utf8').split(/\r?\n/);
  let p = 0;
  while (p < data.length && data[p].trim() === '') p++;
  const header = data[p++].trim().split(/\s+/).map(Number);
  const L = header[0], C = header[1];

  const grid = [];
  for (let i = 0; i < L; i++) {
    grid.push(data[p++] || '');
  }

  // localizar 'o'
  let sr = -1, sc = -1;
  for (let r = 0; r < L; r++) {
    for (let c = 0; c < C; c++) {
      if (grid[r][c] === 'o') { sr = r; sc = c; }
    }
  }

  const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  const key = (r, c) => r * 200 + c;
  const visited = new Set();

  function pathNeighbors(r, c) {
    const res = [];
    for (const [dr, dc] of DIRS) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nr >= L || nc < 0 || nc >= C) continue;
      const ch = grid[nr][nc];
      if (ch === 'H' || ch === 'o') res.push([nr, nc]);
    }
    return res;
  }

  visited.add(key(sr, sc));
  let cr, cc;
  const startCands = pathNeighbors(sr, sc).filter(([r, c]) => !visited.has(key(r, c)));

  if (startCands.length === 0) {
    cr = sr; cc = sc;
  } else {
    [cr, cc] = startCands[0];
    for (;;) {
      visited.add(key(cr, cc));
      const cands = pathNeighbors(cr, cc).filter(([r, c]) => !visited.has(key(r, c)));
      if (cands.length !== 1) break; // sem próximo passo -> posição atual de Hermione
      [cr, cc] = cands[0];
    }
  }

  process.stdout.write((cr + 1) + ' ' + (cc + 1) + '\n');
})();
